arguments.script:
var previous=UnityEngine.SceneManagement.SceneManager.GetActiveScene(); if(previous.isDirty) throw new System.Exception("Unsaved scene; preserving user work"); var previousPath=previous.path;
try {
 UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level01.unity");
 var c=UnityEngine.Camera.main; var brain=c.GetComponent<Cinemachine.CinemachineBrain>(); if(brain)brain.enabled=false; c.transform.position=new UnityEngine.Vector3(-30,-1.8f,-10); FirstLevelWater.Attach();
 var water=c.GetComponent<FirstLevelWater>();
 var mat=(UnityEngine.Material)typeof(FirstLevelWater).GetField("material",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(water);
 water.alignToPlatformMiddle=false;water.waterHeight=-4.4f;var start=c.transform.position;
 for(int n=0;n<2;n++) {
 c.transform.position=start+UnityEngine.Vector3.right*(n*2f);
 foreach(var b in c.GetComponents<UnityEngine.MonoBehaviour>()) if(b is KitLandscape || b is FirstLevelMoonlight || b is FirstLevelWater) b.SendMessage("LateUpdate",UnityEngine.SendMessageOptions.DontRequireReceiver);
 mat.SetFloat("_Clock",10);mat.SetFloat("_CameraMotion",0);
 var refl=UnityEngine.GameObject.Find("Water reflection camera").GetComponent<UnityEngine.Camera>(); refl.Render();
 var rt=new UnityEngine.RenderTexture(1280,720,24); var old=c.targetTexture; var active=UnityEngine.RenderTexture.active;
 var tex=new UnityEngine.Texture2D(1280,720,UnityEngine.TextureFormat.RGB24,false);
 try{c.targetTexture=rt;c.Render();UnityEngine.RenderTexture.active=rt;tex.ReadPixels(new UnityEngine.Rect(0,0,1280,720),0,0);tex.Apply();System.IO.File.WriteAllBytes("scripts/water-20261112/ten-layers/pan-"+n+".png",tex.EncodeToPNG());}
 finally{c.targetTexture=old;UnityEngine.RenderTexture.active=active;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}
 UnityEngine.Debug.Log("pan="+n+" offset="+mat.GetVector("_CameraOffset"));
 }
} finally {if(!string.IsNullOrEmpty(previousPath))UnityEditor.SceneManagement.EditorSceneManager.OpenScene(previousPath);}
